// A test file that breaks each limit of GO-4 as limits.go does, which golangci-lint must not report: the tests are
// left out of the limits (GO-3).
package limits

import "testing"

// TestBranchy calls branchyCase, a function of a test with a cyclomatic complexity of 16 (GO-4).
func TestBranchy(t *testing.T) {
	if branchyCase(1) != Branchy(1) || nestedCase(true, true, true, true, true, true) != 1 || len(padding) == 0 {
		t.Fatal("the cases differ")
	}
}

// branchyCase has a cyclomatic complexity of 16, one plus one per case, as Branchy (GO-4).
func branchyCase(n int) string {
	switch n {
	case 1:
		return "a"
	case 2:
		return "b"
	case 3:
		return "c"
	case 4:
		return "d"
	case 5:
		return "e"
	case 6:
		return "f"
	case 7:
		return "g"
	case 8:
		return "h"
	case 9:
		return "i"
	case 10:
		return "j"
	case 11:
		return "k"
	case 12:
		return "l"
	case 13:
		return "m"
	case 14:
		return "n"
	case 15:
		return "o"
	}
	return ""
}

// nestedCase has a cognitive complexity of 21, six ifs each nested in the one before, as Nested (GO-4).
func nestedCase(a, b, c, d, e, f bool) int {
	if a {
		if b {
			if c {
				if d {
					if e {
						if f {
							return 1
						}
					}
				}
			}
		}
	}
	return 0
}

